--Level 2 — Revenue & Business KPIs

--Q12

--English:
--What is the total revenue generated by each pizza category?
SELECT PT.Category, SUM(P.Price * OD.Quantity) AS TotalRevenue
FROM PizzaTypes PT
JOIN Pizzas P
ON PT.PizzaTypeId = P.PizzaTypeId
JOIN OrderDetails OD
ON P.PizzaId = OD.PizzaId
GROUP BY PT.Category
ORDER BY TotalRevenue DESC


--Q13

--English:
--Which pizza generates the highest revenue?
SELECT TOP 1 
PT.Name, SUM(P.Price * OD.Quantity) AS TotalRevenue
FROM PizzaTypes PT
JOIN Pizzas P
ON PT.PizzaTypeId = P.PizzaTypeId
JOIN OrderDetails OD
ON P.PizzaId = OD.PizzaId
GROUP BY PT.Name
ORDER BY TotalRevenue DESC

--Q14

--English:
--Which pizza generates the lowest revenue?
SELECT TOP 1 
PT.Name, SUM(P.Price * OD.Quantity) AS TotalRevenue
FROM PizzaTypes PT
JOIN Pizzas P
ON PT.PizzaTypeId = P.PizzaTypeId
JOIN OrderDetails OD
ON P.PizzaId = OD.PizzaId
GROUP BY PT.Name
ORDER BY TotalRevenue

--Q15

--English:
--What is the average order value?
SELECT AVG(TotalRevenue) AS AvgRevenue
FROM (
SELECT OD.OrderId, SUM(P.Price * OD.Quantity) AS TotalRevenue
FROM PizzaTypes PT
JOIN Pizzas P
ON PT.PizzaTypeId = P.PizzaTypeId
JOIN OrderDetails OD
ON P.PizzaId = OD.PizzaId
GROUP BY OD.OrderId
) AS TotalOrders


--Q16

--English:
--What is the largest order based on the number of pizzas?
SELECT MAX(NumberOfPizzas) AS MaxPizzasInOrder
FROM (

SELECT OD.OrderId, SUM(OD.Quantity) AS NumberOfPizzas
FROM Pizzas P
JOIN OrderDetails OD
ON P.PizzaId = OD.PizzaId
GROUP BY OD.OrderId
) AS OrderTotals

--Q17

--English:
--What is the largest order based on revenue?
SELECT MAX(TotalRevenue) AS MaxTotalRevenue
FROM (
SELECT OD.OrderId, SUM(P.Price * OD.Quantity) AS TotalRevenue
FROM Pizzas P
JOIN OrderDetails OD
ON P.PizzaId = OD.PizzaId
GROUP BY OD.OrderId
) AS OrderTotals

--Q18

--English:
--Which pizza category generates the highest revenue?

SELECT TOP 1
PT.Category,
SUM(P.Price * OD.Quantity) AS TotalRevenue
FROM PizzaTypes PT
JOIN Pizzas P
ON PT.PizzaTypeId = P.PizzaTypeId
JOIN OrderDetails OD
ON P.PizzaId = OD.PizzaId
GROUP BY PT.Category
ORDER BY TotalRevenue DESC

--Q19

--English:
--Which pizza size generates the lowest revenue?
SELECT TOP 1
P.Size,
SUM(P.Price * OD.Quantity) AS TotalRevenue
FROM Pizzas P
JOIN OrderDetails OD
ON P.PizzaId = OD.PizzaId
GROUP BY P.Size
ORDER BY TotalRevenue 